let musicAnalyzer;
var particles_a = [];
var particles_b = [];
var particles_c = [];
var particles_bg = [];
var nums =	300;
var noiseScale = 800;
let font, fontsize = 15;
let colorCanvas = 0; 				//change the canvas color: 0 is black, 255 is white

//Change the color for line A
let R1 = 	66;
let G1 = 	229;
let B1 = 	244;

//Change the color for line B
let R2 = 	84;
let G2 = 	62;
let B2 =	199;

//Change the color for line C
let R3 = 	198;
let G3 = 	27;
let B3 =	136;

//Change the color for the background effect
let Rbg = 15;
let Gbg = 100;
let Bbg =	80;

function keyPressed() {
	if (key == 's') saveImage();						//Press S to save your image
}

function preload() {
  soundFormats('mp3', 'ogg');
  music = loadSound('https://openprocessing.org/sketch/1207378/files/idont.mp3');         //Load your own track to paint with
	font = loadFont("https://openprocessing.org/sketch/1207378/files/Roboto-Regular.ttf");
}

function setup() {
  music.setVolume(1);
  music.play();
	musicAnalyzer = new p5.FFT();
  musicAnalyzer.setInput(music);
	createCanvas(1280, 720);
	for(var i = 0; i < nums; i++){
		particles_a[i] = new Particle(random(0, width),random(0,height));
		particles_b[i] = new Particle(random(0, width),random(0,height));
		particles_c[i] = new Particle(random(0, width),random(0,height));
		particles_bg[i] = new Particle(random(0, width),random(0,height));
	}
	textFont(font);
  textSize(fontsize);
  textAlign(LEFT, CENTER);
	background(colorCanvas);
}

function draw() {

	let musicAnalyzed = musicAnalyzer.analyze();

  var bass    = musicAnalyzer.getEnergy("bass");
  var mid     = musicAnalyzer.getEnergy("mid");     
  var treble  = musicAnalyzer.getEnergy("treble");

  var mapBass     = map( bass, 0, 255, -100, 100 );
  var mapMid      = map( mid, 0, 255, -150, 150 );
  var mapTreble   = map( treble, 0, 255, -200, 200 );

	var soundArray = [mapBass,mapMid,mapTreble];

	let spectrum = musicAnalyzer.analyze();

	noStroke();
	smooth();
	for(var i = 0; i < nums; i++){
		var radius = map(i,0,nums,1,2);
		var alpha = map(i,0,nums,0,250);

		fill(color(Rbg+((mapMid+soundArray[Math.floor(Math.random() * soundArray.length)])/10),Gbg+((mapBass+soundArray[Math.floor(Math.random() * soundArray.length)])/10),Bbg+((mapTreble+soundArray[Math.floor(Math.random() * soundArray.length)])/10),soundArray[Math.floor(Math.random() * soundArray.length)]/50));
		particles_bg[i].move(soundArray[Math.floor(Math.random() * soundArray.length)]*2);
		particles_bg[i].display(soundArray[Math.floor(Math.random() * soundArray.length)]/2);
		particles_bg[i].checkEdge();

		fill(color(R1+(mapTreble/10), G1+(mapBass/10), B1+(mapMid/10),alpha));
		particles_a[i].move(soundArray[Math.floor(Math.random() * soundArray.length)]);
		particles_a[i].display(mapMid/30);
		particles_a[i].checkEdge(soundArray[Math.floor(Math.random() * soundArray.length)]);

		fill(color(R2+(mapBass/20), G2+(mapMid/10), B2+(mapTreble/10),alpha));
		particles_b[i].move(soundArray[Math.floor(Math.random() * soundArray.length)]);
		particles_b[i].display(mapTreble/30);
		particles_b[i].checkEdge(soundArray[Math.floor(Math.random() * soundArray.length)]);

		fill(color(R3+(mapTreble/10), G3+(mapMid/10), B3+(mapBass/10),alpha));
		particles_c[i].move(soundArray[Math.floor(Math.random() * soundArray.length)]);
		particles_c[i].display(mapBass/30);
		particles_c[i].checkEdge(soundArray[Math.floor(Math.random() * soundArray.length)]);
	}  

}

function Particle(x, y){
	this.dir = createVector(0, 0);
	this.vel = createVector(0, 0);
	this.pos = createVector(x, y);
	this.speed = 0.6;

	this.move = function(direction){
		var angle = noise(this.pos.x/(noiseScale-direction), this.pos.y/(noiseScale-direction))*TWO_PI*noiseScale;
		this.dir.x = cos(angle);
		this.dir.y = sin(angle);
		this.vel = this.dir.copy();
		this.vel.mult(this.speed-(direction/50));
		this.pos.add(this.vel);
	}

	this.checkEdge = function(more){
		if(this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0){
			this.pos.x = random(more/2, width);
			this.pos.y = random(more/2, height);
		}
	}

	this.display = function(r){
		ellipse(this.pos.x, this.pos.y, r, r);
	}

}
function saveImage(){
	noLoop();
	fill(255);
  text("Painted using: "+music.file, 10, 700);
	save('Music Painting - '+music.file+'.png');
	music.pause();
}

